/* Bovitech Super App — 📦 Stock and ordering (Inventory → Stock). Stock lives in the office and in each vehicle, by batch and expiry.
   • Used on a record → comes out of the record's vehicle when the record is finalised (and goes back if it's reopened).
   • 📷 Scan a barcode on a record → it's added to the record (and so the invoice).
   • Restock: each vehicle's usual amounts make a "top up the car" list; tick what you moved. Move anything by hand, either way.
   • Equipment (surgical kits…): back to the office for cleaning, then on the vehicle's restock list once clean.
   • Orders: what's below its minimum, grouped by supplier → a purchase order → send it → receive it with batch and expiry. */
'use strict';
['stk', 'stkmv', 'stkpo', 'stkeq'].forEach((k) => { if (typeof BOOK_KINDS !== 'undefined' && !BOOK_KINDS.includes(k)) BOOK_KINDS.push(k); }); // synced with everything else
const STK = { tab: 'stock', q: '', loc: 'all', show: 'all', sel: null, po: null, veh: null };
const stkL = (k) => (D && (D[k] || (D[k] = []))) || [];
const stkCfg = () => { let r = crCfg('stkcfg'); return r || { id: 'stkcfg', cfg: 'stkcfg', vehicles: [['COWVET', '2020 Toyota LandCruiser 200 Series'], ['COWVET2', '2016 Toyota Hilux'], ['COWVET3', '2025 Toyota Hilux']].map(([n, d]) => ({ id: 'veh-' + n.toLowerCase(), name: n, desc: d })), sup: { 'Prime Animal Health': { minTotal: 1000, note: 'Free freight on orders of $1,000 ex GST or more' } }, usual: {}, byStaff: {}, day: {}, poNext: 1, _new: true }; }; // the practice's vehicles to start with
function stkCfgSave(f) { let r = crCfg('stkcfg'); if (!r) { r = stkCfg(); delete r._new; crList('crcfg').push(r); } f(r); touch(r); save(); if (window.Sync) Sync.soon(); }
const stkVehicles = () => (stkCfg().vehicles || []).filter((v) => !v.gone);
const stkLocName = (l) => (l === 'office' ? '🏢 Office' : '🚗 ' + ((stkVehicles().find((v) => v.id === l) || (stkCfg().vehicles || []).find((v) => v.id === l) || {}).name || 'Vehicle'));
const stkLocs = () => ['office', ...stkVehicles().map((v) => v.id)];
const stkTracked = (p) => p && !p.items && (p.track != null ? !!p.track : ['med', 'consumable', 'merch'].includes(p.cat)) && p.active !== false; /* "Tracked in inventory" on the item (stock2.js) */
const stkLots = (prod, loc) => stkL('stk').filter((x) => !x.gone && x.prod === prod && (!loc || x.loc === loc));
const stkQty = (prod, loc) => crR4(stkLots(prod, loc).reduce((s, x) => s + (+x.qty || 0), 0));
const stkUnit = (p) => (p && p.unit && p.unit !== 'each' ? p.unit : '');
const stkFmt = (p, n) => `${+(+n).toFixed(2)}${stkUnit(p) ? ' ' + stkUnit(p) : ''}`;
const stkExpSoon = (x, days) => x.exp && x.exp <= bkAdd(bkToday(), days == null ? 60 : days);
function stkLog(m) { const r = { id: uid('mv'), at: Date.now(), by: (SBAuth.staff && SBAuth.staff.id) || null, ...m }; touch(r); stkL('stkmv').push(r); return r; }
function stkAdd(prod, qty, loc, batch, exp, why, ref) { qty = +qty || 0; if (!qty) return; let lot = stkL('stk').find((x) => !x.gone && x.prod === prod && x.loc === loc && (x.batch || '') === (batch || '') && (x.exp || '') === (exp || ''));
  if (!lot) { lot = { id: uid('lot'), prod, loc, batch: batch || '', exp: exp || '', qty: 0 }; stkL('stk').push(lot); } lot.qty = crR4((+lot.qty || 0) + qty); if (Math.abs(lot.qty) < 1e-6) lot.gone = true; touch(lot);
  if (why) stkLog({ prod, qty, to: loc, batch: batch || '', exp: exp || '', why, ref }); }
function stkTake(prod, qty, loc, why, ref) { // earliest expiry first → [{ batch, exp, qty }]
  let left = +qty || 0; const used = []; const L = stkLots(prod, loc).filter((x) => x.qty > 0).sort((a, b) => (a.exp || '9999').localeCompare(b.exp || '9999'));
  for (const lot of L) { if (left <= 0) break; const n = Math.min(lot.qty, left); lot.qty = crR4(lot.qty - n); if (lot.qty <= 1e-6) lot.gone = true; touch(lot); used.push({ batch: lot.batch, exp: lot.exp, qty: n }); left = crR4(left - n); }
  if (left > 0) { stkAdd(prod, -left, loc, '', '', null); used.push({ batch: '', exp: '', qty: left, short: true }); } // more used than recorded: it goes below zero so the count shows it
  if (why) stkLog({ prod, qty: -(+qty || 0), from: loc, why, ref, lots: used }); return used; }
function stkMove(prod, qty, from, to, why) { const used = stkTake(prod, qty, from, null); used.forEach((u) => stkAdd(prod, u.qty, to, u.short ? '' : u.batch, u.short ? '' : u.exp, null)); stkLog({ prod, qty: +qty, from, to, why: why || 'Moved', lots: used }); }
const stkSync = () => { save(); if (window.Sync) Sync.soon(); };

/* ---------- the vehicle for a record (the cars swap from day to day) ---------- */
function stkDayVeh(sid, date) { const c = stkCfg(); return (c.day || {})[sid + ':' + date] || (c.byStaff || {})[sid] || null; }
function stkRecVeh(r) { if (r.vehicle !== undefined) return r.vehicle; const sid = (r.staff || [])[0]; const v = sid ? stkDayVeh(sid, r.date || bkToday()) : null; return v || (stkVehicles().length ? null : 'office'); }
function stkRecBar(r) { if (!stkVehicles().length && !('BarcodeDetector' in window)) return `<div class="card stk-recbar"><button class="btn small" data-act="stk-scan" data-rec="${r.id}">📷 Scan</button> <span class="hint">Add vehicles in Scheduling → Vehicles to take stock out of the right one.</span></div>`;
  const v = stkRecVeh(r); const fin = r.status === 'final';
  return `<div class="card stk-recbar"><label style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><b>🚗 Stock from</b><select data-act="stk-recveh" data-rec="${r.id}" ${fin ? 'disabled' : ''}><option value="">Choose…</option>${stkLocs().map((l) => `<option value="${l}" ${v === l ? 'selected' : ''}>${h(stkLocName(l))}</option>`).join('')}</select></label>
    ${fin ? '' : `<button class="btn small primary" data-act="stk-scan" data-rec="${r.id}">📷 Scan what you used</button>`}<span class="hint">${fin ? (r.stockLoc ? 'Taken out of ' + h(stkLocName(r.stockLoc)) : '') : 'Medications and consumables come out of this when the record is finalised.'}</span></div>`; }
// replaces the old single stock count: out of the record's vehicle, by batch, and back exactly the same way if it's reopened
window.crStock = function (r, dir) {
  if (dir > 0) { const loc = stkRecVeh(r) || 'office'; r.stockLoc = loc; (r.items || []).forEach((it) => { const p = crProd(it.prod); if (!stkTracked(p)) return; const u = it.as === 'pack' ? (+it.qty || 0) * (+p.pack || 1) : +it.qty || 0; if (!u) return;
    if (p.stock != null) { p.stock = crR4(p.stock - u); touch(p); } // the old single count, if it was being used
    it.lots = stkTake(p.id, u, loc, 'Used — ' + ((IDX.biz.get(r.bid) || {}).name || 'record'), r.id); if (!it.batch && it.lots[0] && it.lots[0].batch) it.batch = it.lots[0].batch; }); }
  else { const loc = r.stockLoc || 'office'; (r.items || []).forEach((it) => { const p = crProd(it.prod); if (!p || !it.lots) return; it.lots.forEach((u) => stkAdd(p.id, u.qty, loc, u.short ? '' : u.batch, u.short ? '' : u.exp, null)); if (p.stock != null) { p.stock = crR4(p.stock + it.lots.reduce((s2, u) => s2 + u.qty, 0)); touch(p); } stkLog({ prod: p.id, qty: it.lots.reduce((s, u) => s + u.qty, 0), to: loc, why: 'Record reopened', ref: r.id }); delete it.lots; }); }
  stkSync(); };

/* ---------- 📷 scanning ---------- */
function stkByBarcode(code) { const c = String(code || '').trim(); if (!c) return []; const hit = crList('crprod').filter((p) => !p.gone && (p.barcode === c || (p.barcodes || []).includes(c))); if (!hit.length) return [];
  const out = [...hit]; hit.forEach((p) => { const base = (p.name || '').replace(/\s*-\s*(full pack|single dose|single|full can|full)\b.*$/i, '').trim().toLowerCase(); if (base) crList('crprod').forEach((q) => { if (!q.gone && q.active !== false && !out.includes(q) && (q.name || '').toLowerCase().startsWith(base + ' -')) out.push(q); }); }); return out; }
async function stkScan(rid) { const r = crGet('crrec', rid); if (!r) return; const can = 'BarcodeDetector' in window && navigator.mediaDevices; let det = null, stream = null, stop = false;
  const box = document.createElement('div'); box.id = 'stkscan'; box.innerHTML = `<div class="vc-in"><b>${STK_BC} Scan what you used</b><div class="hint">Point the camera at the barcode. Each one scanned is added to the record.</div>${can ? '<video id="stk-v" playsinline muted style="width:100%;max-height:45vh;border-radius:10px;background:#000;margin-top:6px"></video>' : '<div class="hint" style="margin:6px 0">This phone can\'t read barcodes with the camera — type the number from under the barcode instead.</div>'}
    <div class="cr-row" style="margin-top:6px"><input id="stk-code" inputmode="numeric" aria-label="Barcode number" style="flex:1;padding:9px;font-size:16px;border:1px solid var(--line);border-radius:9px"><button class="btn small" data-act="stk-code">Add</button></div><div id="stk-added" class="hint"></div><div class="actions"><button class="btn" data-act="stk-scanphoto">📸 No barcode? Use a photo</button><button class="btn primary" data-act="stk-scandone">Done</button></div></div>`;
  document.body.appendChild(box); const added = []; const show = () => { const el = document.getElementById('stk-added'); if (el) el.innerHTML = added.map((x) => '✓ ' + h(x)).join('<br>'); };
  const got = async (code, pp) => { const L = pp ? [pp] : stkByBarcode(code); if (!L.length) { toast('No product has barcode ' + code + ' — add it in the price list (Barcode)'); return; } let p = L[0];
    if (L.length > 1) { const ok = await askBox('Which one?', `<div class="f">${L.map((q, i) => `<label class="bk-radio" style="display:flex"><input type="radio" name="sb" data-ask="i" value="${i}" ${i ? '' : 'checked'}> ${h(q.name)}</label>`).join('')}</div>`, 'Next'); if (!ok) return; p = L[+ASK_FORM.i || 0]; }
    const md = p.cat === 'med' || p.cat === 'consumable'; const ok2 = await askBox(p.name, `<div class="f"><label>How much${stkUnit(p) ? ' (' + h(p.unit) + ')' : ''}?</label><input type="number" data-ask="q" min="0" step="any" value="1" style="width:140px;padding:9px;font-size:18px"></div>${md && p.pack ? `<label class="bk-radio" style="display:flex"><input type="checkbox" data-askchk="pk"> Whole ${h(p.packName || 'bottle')}s (${p.pack} ${h(p.unit || '')})</label>` : ''}`, 'Add to the record'); if (!ok2) return;
    const q = +ASK_FORM.q || 0; if (!q) return; r.items = r.items || []; r.items.push({ id: uid('it'), prod: p.id, qty: q, as: ASK_FORM.pk ? 'pack' : 'dose', mode: p.cat === 'merch' ? 'merch' : p.cat === 'consumable' ? 'cons' : 'admin', scanned: code }); touch(r); save(); crInvSync(r); if (window.Sync) Sync.soon(); added.push(`${p.name} × ${q}`); show(); };
  box.addEventListener('click', async (e) => { const a = e.target.dataset && e.target.dataset.act; if (a === 'stk-code') { const i = document.getElementById('stk-code'); const c = i.value.trim(); i.value = ''; if (c) await got(c); } if (a === 'stk-scanphoto') { const v = document.getElementById('stk-v'); const src = v && v.videoWidth ? v : await stkPhotoPick(true); if (!src) return; const p = await stkRecognise(src); if (p) await got('', p); }
    if (a === 'stk-scandone') { stop = true; if (stream) stream.getTracks().forEach((t) => t.stop()); box.remove(); renderAll(); } });
  if (!can) return;
  try { det = new BarcodeDetector({ formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39', 'qr_code', 'data_matrix', 'itf'] }); stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); const v = document.getElementById('stk-v'); v.srcObject = stream; await v.play(); }
  catch (e) { toast("Couldn't open the camera — type the barcode number instead"); return; }
  let last = '', lastAt = 0, busy = false; const tick = async () => { if (stop) return; if (!busy) { try { const v = document.getElementById('stk-v'); const L = v ? await det.detect(v) : []; const c = L[0] && L[0].rawValue; if (c && (c !== last || Date.now() - lastAt > 4000)) { last = c; lastAt = Date.now(); busy = true; try { navigator.vibrate && navigator.vibrate(60); } catch (x) { } await got(c); busy = false; } } catch (x) { busy = false; } } setTimeout(tick, 350); }; tick(); }

/* ---------- Inventory → Stock ---------- */
const STK_TABS = [['stock', 'Stock'], ['restock', 'Restock vehicles'], ['equip', 'Equipment'], ['orders', 'Orders'], ['history', 'History'], ['vehicles', 'Vehicles']];
function stkHtml() { const t = STK.tab;
  const tabs = `<div class="chips" style="margin-bottom:8px">${STK_TABS.map(([k, l]) => `<button class="chip ${t === k ? 'on' : ''}" data-act="stk-tab" data-v="${k}">${l}${k === 'orders' && stkReorder().length ? ` <span class="cn">${stkReorder().length}</span>` : ''}</button>`).join('')}</div>`;
  const body = t === 'restock' ? stkRestockHtml() : t === 'equip' ? stkEquipHtml() : t === 'orders' ? (STK.po ? stkPoHtml(STK.po) : stkOrdersHtml()) : t === 'history' ? stkHistHtml() : t === 'vehicles' ? stkVehHtml() : stkStockHtml();
  return `<div class="d-wrap"><h2 class="sec-h" style="font-size:26px">📦 Stock and ordering</h2>${tabs}${body}</div>`; }
function stkStockHtml() { if (STK.sel) return stkProdHtml(STK.sel); const q = STK.q.toLowerCase().trim(); const locs = stkLocs(); const L = crList('crprod').filter((p) => !p.gone && stkTracked(p) && (!q || (p.name + ' ' + (p.code || '')).toLowerCase().includes(q)));
  const rows = L.map((p) => { const by = {}; locs.forEach((l) => (by[l] = stkQty(p.id, l))); const tot = Object.values(by).reduce((a, b) => a + b, 0); const lots = stkLots(p.id); const soon = lots.filter((x) => x.qty > 0 && stkExpSoon(x)); const low = p.min && tot <= p.min; return { p, by, tot, soon, low, has: lots.length }; })
    .filter((x) => STK.show === 'low' ? x.low : STK.show === 'exp' ? x.soon.length : STK.show === 'have' ? x.has : true).sort((a, b) => (b.low - a.low) || a.p.name.localeCompare(b.p.name));
  const val = crR2(stkL('stk').filter((x) => !x.gone && x.qty > 0).reduce((s, x) => { const p = crProd(x.prod); return s + x.qty * (+(p && (p.cost || p.supPrice)) || 0); }, 0));
  return `<div class="search" style="margin-bottom:6px"><input id="stk-q" type="search" placeholder="Search stock" value="${h(STK.q)}" autocomplete="off" aria-label="Search stock"></div>
    <div class="chips">${[['all', 'All'], ['have', 'In stock'], ['low', '⚠ Below minimum'], ['exp', '⏳ Expiring in 60 days']].map(([k, l]) => `<button class="chip ${STK.show === k ? 'on' : ''}" data-act="stk-show" data-v="${k}">${l}</button>`).join('')}</div>
    <div class="actions"><button class="btn small primary" data-act="stk-in">➕ Stock in (no order)</button><button class="btn small" data-act="stk-movenew">⇄ Move stock</button><button class="btn small" data-act="stk-count">📝 Stocktake</button></div>
    <div class="hint" style="margin:4px 0">Stock value (at cost): <b>${crMoney(val)}</b> ex GST · tap an item for its batches, expiry dates and history.</div>
    <div class="card" style="overflow-x:auto"><table class="ezy-t"><tr><th>Item</th>${locs.map((l) => `<th>${h(stkLocName(l))}</th>`).join('')}<th>Total</th><th>Min</th><th>Max</th></tr>
    ${rows.slice(0, 400).map((x) => `<tr class="bk-tap" data-act="stk-open" data-id="${x.p.id}"><td><b>${h(x.p.name)}</b>${x.soon.length ? ' <span class="pill" style="font-size:11px">⏳ ' + bkDate(x.soon.map((l) => l.exp).sort()[0], { day: 'numeric', month: 'short' }) + '</span>' : ''}</td>${locs.map((l) => `<td>${x.by[l] ? stkFmt(x.p, x.by[l]) : '—'}</td>`).join('')}<td ${x.low ? 'style="color:var(--red);font-weight:800"' : ''}>${stkFmt(x.p, x.tot)}</td><td>${x.p.min ? stkFmt(x.p, x.p.min) : ''}</td><td>${x.p.max ? stkFmt(x.p, x.p.max) : ''}</td></tr>`).join('') || `<tr><td colspan="${locs.length + 3}" class="hint">Nothing here.</td></tr>`}</table></div>`; }
function stkProdHtml(id) { const p = crProd(id); if (!p) { STK.sel = null; return stkStockHtml(); } const lots = stkLots(id).sort((a, b) => a.loc.localeCompare(b.loc) || (a.exp || '').localeCompare(b.exp || '')); const mv = stkL('stkmv').filter((m) => m.prod === id).sort((a, b) => b.at - a.at).slice(0, 60);
  return `<div class="actions"><button class="btn small" data-act="stk-back">‹ Stock</button><button class="btn small" data-act="cr-prodedit" data-id="${p.id}">✏️ Price list item</button></div><h3>${h(p.name)}</h3>
    <div class="hint">Minimum ${p.min ? stkFmt(p, p.min) : 'not set'} · maximum ${p.max ? stkFmt(p, p.max) : '—'}${p.moq ? ' · the supplier\'s minimum order ' + stkFmt(p, p.moq) : ''}${p.supName || p.supplier ? ' · supplier ' + h((IDX.biz.get(p.supplier) || {}).name || p.supName) : ''} <button class="btn small" data-act="stk-min" data-id="${p.id}">✏️</button></div>
    <div class="card"><h3>Where it is</h3>${lots.length ? `<table class="ezy-t"><tr><th>Place</th><th>Batch</th><th>Expiry</th><th>Amount</th><th></th></tr>${lots.map((x) => `<tr><td>${h(stkLocName(x.loc))}</td><td>${h(x.batch || '—')}</td><td ${stkExpSoon(x, 0) ? 'style="color:var(--red)"' : ''}>${x.exp ? bkDate(x.exp, { day: 'numeric', month: 'short', year: 'numeric' }) : '—'}</td><td>${stkFmt(p, x.qty)}</td><td><button class="btn small" data-act="stk-move" data-lot="${x.id}">⇄</button></td></tr>`).join('')}</table>` : '<div class="hint">None in stock.</div>'}
      <div class="actions"><button class="btn small primary" data-act="stk-next" data-id="${p.id}">🧾 Add to the next ${h(stkSupName(p) === 'No supplier set' ? '' : stkSupName(p))} order</button><button class="btn small" data-act="stk-photo" data-id="${p.id}">📸 Add a photo</button><button class="btn small" data-act="stk-in" data-id="${p.id}">➕ Stock in</button><button class="btn small" data-act="stk-movenew" data-id="${p.id}">⇄ Move</button><button class="btn small" data-act="stk-count" data-id="${p.id}">📝 Count</button></div></div>
    <div class="card"><h3>History</h3>${mv.map(stkMvRow).join('') || '<div class="hint">Nothing yet.</div>'}</div>`; }
function stkMvRow(m) { const p = crProd(m.prod); return `<div class="kv"><div class="k">${new Date(m.at).toLocaleString('en-AU', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' })}</div><div class="v">${p ? '<b>' + h(p.name) + '</b> ' : ''}${m.qty > 0 ? '+' : ''}${stkFmt(p, m.qty)} ${m.from ? 'from ' + h(stkLocName(m.from)) : ''} ${m.to ? 'to ' + h(stkLocName(m.to)) : ''}<br><span class="hint">${h(m.why || '')}${m.by ? ' — ' + h(Bk.pname(m.by)) : ''}${m.batch ? ' · batch ' + h(m.batch) : ''}</span></div></div>`; }
function stkHistHtml() { const L = stkL('stkmv').slice().sort((a, b) => b.at - a.at).slice(0, 300); return `<div class="card">${L.map(stkMvRow).join('') || '<div class="hint">Nothing yet.</div>'}</div>`; }

/* ---------- vehicles ---------- */
function stkVehHtml() { const V = stkVehicles(); const c = stkCfg(); const ppl = Bk.people();
  return `<div class="card"><h3><span class="sp">Vehicles</span><button class="btn small" data-act="stk-vehadd">➕ Add a vehicle</button></h3>${V.map((v) => `<div class="kv" style="align-items:center"><div class="v"><b>🚗 ${h(v.name)}</b>${v.desc ? ` <span class="hint">${h(v.desc)}</span>` : ''}</div><button class="btn small" data-act="stk-vehren" data-id="${v.id}">✏️</button><button class="btn small" data-act="stk-vehdel" data-id="${v.id}">🗑</button></div>`).join('') || '<div class="hint">None yet — add each car or ute that carries stock.</div>'}</div>
    ${V.length ? `<div class="card"><h3>Who usually drives which</h3><div class="hint">The cars swap — this is only the starting choice. Change it for a day on that person's Day prep, or on the record itself.</div>${ppl.map((p) => `<div class="kv" style="align-items:center"><div class="v">${h(p.preferred_name || p.full_name)}</div><select data-act="stk-bystaff" data-sid="${p.id}"><option value="">—</option>${V.map((v) => `<option value="${v.id}" ${(c.byStaff || {})[p.id] === v.id ? 'selected' : ''}>${h(v.name)}</option>`).join('')}</select></div>`).join('')}</div>` : ''}`; }

/* ---------- restock ---------- */
function stkRestockHtml() { const V = stkVehicles(); if (!V.length) return '<div class="card"><div class="hint">Add your vehicles first (the Vehicles tab).</div></div>'; const v = STK.veh && V.find((x) => x.id === STK.veh) ? STK.veh : V[0].id; STK.veh = v; const us = (stkCfg().usual || {})[v] || {};
  const rows = Object.entries(us).map(([pid, n]) => { const p = crProd(pid); if (!p) return null; const have = stkQty(pid, v); return { p, n: +n, have, need: Math.max(0, crR4(+n - have)), office: stkQty(pid, 'office') }; }).filter(Boolean).sort((a, b) => (b.need > 0) - (a.need > 0) || a.p.name.localeCompare(b.p.name));
  const eq = stkL('stkeq').filter((e) => !e.gone && e.home === v && e.loc !== v && e.state !== 'dirty');
  return `<div class="chips">${V.map((x) => `<button class="chip ${x.id === v ? 'on' : ''}" data-act="stk-veh" data-v="${x.id}">🚗 ${h(x.name)}</button>`).join('')}</div>
    <div class="card"><h3><span class="sp">Top up ${h(stkLocName(v))} from the office</span><button class="btn small" data-act="stk-usualadd" data-v="${v}">➕ Add an item</button></h3><div class="hint">Tick what you put in the vehicle — change the amount if you're taking more (or less) — then tap Move.</div>
    ${rows.length ? `<table class="ezy-t"><tr><th></th><th>Item</th><th>In vehicle</th><th>Usual</th><th>Moving</th><th></th></tr>${rows.map((x) => `<tr><td><input type="checkbox" class="stk-rs" data-id="${x.p.id}" ${x.need > 0 ? 'checked' : ''} style="width:20px;height:20px"></td><td>${h(x.p.name)}<br><span class="hint">office has ${stkFmt(x.p, x.office)}</span></td><td>${stkFmt(x.p, x.have)}</td><td><input type="number" class="stk-us" data-v="${v}" data-id="${x.p.id}" value="${x.n}" min="0" step="any" style="width:70px" aria-label="Usual amount"></td><td><input type="number" class="stk-rq" data-id="${x.p.id}" value="${x.need}" min="0" step="any" style="width:70px" aria-label="Amount to move"></td><td><button class="btn small" data-act="stk-usualdel" data-v="${v}" data-id="${x.p.id}" aria-label="Remove">✕</button></td></tr>`).join('')}</table>` : '<div class="hint">No usual amounts yet — ➕ Add an item for each thing this vehicle carries.</div>'}
    ${eq.length ? `<div class="lbl" style="margin-top:8px">Equipment to put back</div>${eq.map((e) => `<label class="bk-radio" style="display:flex"><input type="checkbox" class="stk-eqr" data-id="${e.id}" checked> 🧰 ${h(e.name)} <span class="hint">(clean, at ${h(stkLocName(e.loc))})</span></label>`).join('')}` : ''}
    <div class="actions"><button class="btn primary" data-act="stk-restock" data-v="${v}">⇄ Move the ticked ones into ${h(stkLocName(v))}</button><button class="btn" data-act="stk-movenew" data-from="${v}" data-to="office">↩ Back to the office…</button></div></div>`; }

/* ---------- equipment ---------- */
function stkEquipHtml() { const E = stkL('stkeq').filter((e) => !e.gone).sort((a, b) => a.name.localeCompare(b.name)); const st = { ready: '✓ Ready', dirty: '🧽 Needs cleaning' };
  return `<div class="card"><h3><span class="sp">🧰 Equipment</span><button class="btn small" data-act="stk-eqadd">➕ Add</button></h3><div class="hint">Kits and gear that travel: a used kit goes back to the office for cleaning, then shows on its vehicle's restock list once it's clean.</div>
    ${E.map((e) => `<div class="kv" style="align-items:center;flex-wrap:wrap"><div class="v" style="flex:1"><b>🧰 ${h(e.name)}</b><br><span class="hint">${h(stkLocName(e.loc))} · ${st[e.state] || '✓ Ready'}${e.home ? ' · belongs in ' + h(stkLocName(e.home)) : ''}</span></div>
      ${e.loc !== 'office' ? `<button class="btn small" data-act="stk-eqdirty" data-id="${e.id}">🧽 Used — back to the office for cleaning</button>` : e.state === 'dirty' ? `<button class="btn small primary" data-act="stk-eqclean" data-id="${e.id}">✓ Cleaned</button>` : ''}<button class="btn small" data-act="stk-eqedit" data-id="${e.id}" aria-label="Change">✏️</button></div>`).join('') || '<div class="hint">None yet.</div>'}</div>`; }

/* ---------- orders ---------- */
function stkReorder() { return crList('crprod').filter((p) => !p.gone && stkTracked(p) && p.min && stkQty(p.id) < p.min && !stkL('stkpo').some((o) => !o.gone && ['draft', 'sent', 'part'].includes(o.status) && (o.lines || []).some((l) => l.prod === p.id))); }
const stkSupName = (p) => (p.supplier && IDX.biz.get(p.supplier) ? IDX.biz.get(p.supplier).name : p.supName || 'No supplier set');
function stkOrdersHtml() { const R = stkReorder(); const g = {}; R.forEach((p) => (g[stkSupName(p)] = g[stkSupName(p)] || []).push(p)); const POs = stkL('stkpo').filter((o) => !o.gone).sort((a, b) => b.at - a.at); const sn = { draft: 'Draft', sent: 'Sent', part: 'Part received', done: 'Received' };
  return `<div class="card"><h3>To order — below their minimum</h3>${Object.keys(g).length ? Object.entries(g).map(([s, L]) => `<div class="kv" style="align-items:flex-start"><div class="v"><b>${h(s)}</b><div class="hint">${L.map((p) => `${h(p.name)}: ${stkFmt(p, stkQty(p.id))} of ${stkFmt(p, p.min)}`).join('<br>')}</div></div><button class="btn small primary" data-act="stk-ponew" data-sup="${h(s)}">🧾 Make an order</button></div>`).join('') : '<div class="hint">Nothing below its minimum. (Set minimums on each item in Stock.)</div>'}
    <div class="actions"><button class="btn small" data-act="stk-ponew">➕ New order</button></div></div>
    <div class="card"><h3>Orders</h3>${POs.map((o) => `<div class="kv bk-tap" data-act="stk-poopen" data-id="${o.id}"><div class="k">${bkDate(new Date(o.at).toISOString().slice(0, 10), { day: 'numeric', month: 'short' })}</div><div class="v"><b>PO ${h(o.num)}</b> — ${h(o.supName || '')} <span class="pill" style="font-size:11px">${sn[o.status] || o.status}</span><br><span class="hint">${(o.lines || []).length} item${(o.lines || []).length === 1 ? '' : 's'} · ${crMoney((o.lines || []).reduce((s, l) => s + (+l.qty || 0) * (+l.price || 0), 0))} ex GST</span></div></div>`).join('') || '<div class="hint">None yet.</div>'}</div>`; }
function stkPoHtml(id) { const o = stkL('stkpo').find((x) => x.id === id && !x.gone); if (!o) { STK.po = null; return stkOrdersHtml(); } const ed = o.status === 'draft'; const sup = o.sup && IDX.biz.get(o.sup); const em = sup ? (sup.emails || []).map((e) => e.value).filter(Boolean) : [];
  return `<div class="actions"><button class="btn small" data-act="stk-poback">‹ Orders</button></div><h3>Purchase order ${h(o.num)} — ${h(o.supName || 'supplier')}</h3><div class="hint">${o.status === 'draft' ? 'Draft' : o.status === 'sent' ? 'Sent ' + (o.sentAt ? new Date(o.sentAt).toLocaleDateString('en-AU') : '') + (o.sentTo ? ' to ' + h(o.sentTo) : '') : o.status === 'part' ? 'Part received' : 'Received'}</div>
    <div class="card"><table class="ezy-t"><tr><th>Item</th><th>Their code</th><th>Qty</th><th>Price ex GST</th>${o.status !== 'draft' ? '<th>Received</th>' : ''}<th></th></tr>${(o.lines || []).map((l, i) => { const p = crProd(l.prod); return `<tr><td>${h(p ? p.name : l.name || '?')}</td><td>${h((p && p.supCode) || '')}</td><td>${ed ? `<input type="number" class="stk-poq" data-po="${o.id}" data-i="${i}" value="${l.qty}" min="0" step="any" style="width:70px">` : l.qty}</td><td>${crMoney(l.price || 0)}</td>${o.status !== 'draft' ? `<td>${+l.got || 0}</td>` : ''}<td>${ed ? `<button class="btn small" data-act="stk-podel" data-po="${o.id}" data-i="${i}">✕</button>` : ''}</td></tr>`; }).join('')}
      <tr><td colspan="3"><b>Total ex GST</b></td><td><b>${crMoney((o.lines || []).reduce((s, l) => s + (+l.qty || 0) * (+l.price || 0), 0))}</b></td></tr></table>
      ${ed ? `<div class="actions"><button class="btn small" data-act="stk-poadd" data-po="${o.id}">➕ Add an item</button></div>` : ''}
      <div class="f"><label>Note to the supplier</label><textarea class="stk-ponote" data-po="${o.id}" rows="2" ${ed ? '' : 'disabled'}>${h(o.note || '')}</textarea></div></div>
    <div class="actions">${ed ? `<button class="btn primary" data-act="stk-posend" data-po="${o.id}">📧 Send to ${h(em[0] || 'the supplier')}</button>` : ''}${o.status === 'sent' || o.status === 'part' ? `<button class="btn primary" data-act="stk-porecv" data-po="${o.id}">📥 It's arrived — receive it</button>` : ''}<button class="btn" data-act="stk-poprint" data-po="${o.id}">🖨 Print / PDF</button>${ed ? `<button class="btn" data-act="stk-podelpo" data-po="${o.id}" style="color:var(--red)">Delete</button>` : ''}</div>
    ${!em.length && ed ? `<div class="hint">${h(o.supName || 'This supplier')} has no email in the app yet — add one on their business, or it opens your email to type it.</div>` : ''}`; }
function stkPoBody(o) { const b = crBrand ? crBrand() : {}; const rows = (o.lines || []).map((l) => { const p = crProd(l.prod); return `<tr><td>${h((p && p.supCode) || '')}</td><td>${h(p ? p.name : l.name || '')}</td><td style="text-align:right">${l.qty}</td><td style="text-align:right">${crMoney(l.price || 0)}</td></tr>`; }).join('');
  return `<h2>Purchase order ${h(o.num)}</h2><p>Bovitech Veterinary Services · 317 Gull Rock Road, Kalgan WA 6330 · 0499 489 919 · office@bovitech.com.au</p><p>To: ${h(o.supName || '')}<br>Date: ${new Date().toLocaleDateString('en-AU')}</p>
    <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Your code</th><th>Item</th><th>Qty</th><th>Price ex GST</th></tr>${rows}</table>${o.note ? `<p>${h(o.note).replace(/\n/g, '<br>')}</p>` : ''}<p>Please deliver to the address above and quote PO ${h(o.num)} on your invoice. Thank you.</p>`; }
const stkPoText = (o) => `Purchase order ${o.num} — Bovitech Veterinary Services\n\n` + (o.lines || []).map((l) => { const p = crProd(l.prod); return `${l.qty} × ${p ? p.name : l.name || ''}${p && p.supCode ? ' (your code ' + p.supCode + ')' : ''}`; }).join('\n') + (o.note ? '\n\n' + o.note : '') + `\n\nPlease quote PO ${o.num} on your invoice.\n317 Gull Rock Road, Kalgan WA 6330 · 0499 489 919`;
function stkNewPo(supName) { const R = supName ? stkReorder().filter((p) => stkSupName(p) === supName) : []; const p0 = R[0]; let num = ''; stkCfgSave((c) => { num = 'PO' + String(c.poNext || 1).padStart(4, '0'); c.poNext = (c.poNext || 1) + 1; });
  const o = { id: uid('po'), num, at: Date.now(), by: SBAuth.staff && SBAuth.staff.id, status: 'draft', sup: p0 ? p0.supplier || null : (supName && D.businesses.find((b) => !b.gone && b.name === supName) || {}).id || null, supName: supName && supName !== 'No supplier set' ? supName : '', note: '',
    lines: R.map((p) => ({ prod: p.id, qty: Math.max(p.reorder || 0, Math.ceil(crR4(p.min - stkQty(p.id)) * 1) || 1), price: p.supPrice || p.cost || 0 })) }; touch(o); stkL('stkpo').push(o); stkSync(); STK.po = o.id; STK.tab = 'orders'; renderAll(); }

/* ---------- events ---------- */
async function stkPickProd(title) { return typeof crPickProd === 'function' ? await crPickProd(['med', 'consumable', 'merch']) : null; }
const stkLocSel = (k, v) => `<select data-ask="${k}" style="width:100%;padding:9px;font-size:16px;border:1px solid var(--line);border-radius:9px">${stkLocs().map((l) => `<option value="${l}" ${l === v ? 'selected' : ''}>${h(stkLocName(l))}</option>`).join('')}</select>`;
const stkInp = (k, v, t) => `<input data-ask="${k}" ${t ? 'type="' + t + '"' : ''} value="${h(v == null ? '' : v)}" style="width:100%;padding:9px;font-size:16px;border:1px solid var(--line);border-radius:9px">`;
document.addEventListener('click', async (e) => { const el = e.target.closest && e.target.closest('[data-act]'); if (!el) return; const a = el.dataset.act; if (!/^stk-/.test(a)) return; const d = el.dataset; const R = () => { stkSync(); renderAll(); };
  if (a === 'stk-tab') { STK.tab = d.v; STK.sel = null; STK.po = null; renderAll(); } if (a === 'stk-show') { STK.show = d.v; renderAll(); } if (a === 'stk-open') { STK.sel = d.id; renderAll(); } if (a === 'stk-back') { STK.sel = null; renderAll(); } if (a === 'stk-veh') { STK.veh = d.v; renderAll(); }
  if (a === 'stk-scan') stkScan(d.rec);
  if (a === 'stk-in') { const id = d.id || await stkPickProd(); if (!id) return; const p = crProd(id); const ok = await askBox('➕ Stock in — ' + p.name, `<div class="grid2"><div class="f"><label>Amount${stkUnit(p) ? ' (' + h(p.unit) + ')' : ''}</label>${stkInp('q', '', 'number')}</div><div class="f"><label>Into</label>${stkLocSel('loc', 'office')}</div><div class="f"><label>Batch</label>${stkInp('b', '')}</div><div class="f"><label>Expiry</label>${stkInp('x', '', 'date')}</div></div><div class="f"><label>Why</label>${stkInp('w', 'Stock in')}</div>`, 'Add'); if (!ok || !(+ASK_FORM.q)) return; stkAdd(id, +ASK_FORM.q, ASK_FORM.loc || 'office', ASK_FORM.b, ASK_FORM.x, ASK_FORM.w || 'Stock in'); R(); toast('Added'); }
  if (a === 'stk-movenew' || a === 'stk-move') { const lot = d.lot && stkL('stk').find((x) => x.id === d.lot); const id = lot ? lot.prod : d.id || await stkPickProd(); if (!id) return; const p = crProd(id); const from = lot ? lot.loc : d.from || 'office', to = d.to || (from === 'office' ? (stkVehicles()[0] || {}).id || 'office' : 'office');
    const ok = await askBox('⇄ Move — ' + p.name, `<div class="grid2"><div class="f"><label>From</label>${stkLocSel('f', from)}</div><div class="f"><label>To</label>${stkLocSel('t', to)}</div><div class="f"><label>Amount${stkUnit(p) ? ' (' + h(p.unit) + ')' : ''}</label>${stkInp('q', lot ? lot.qty : '', 'number')}</div></div><div class="hint">${stkLocs().map((l) => h(stkLocName(l)) + ': ' + stkFmt(p, stkQty(id, l))).join(' · ')}</div>`, 'Move'); if (!ok || !(+ASK_FORM.q) || ASK_FORM.f === ASK_FORM.t) return; stkMove(id, +ASK_FORM.q, ASK_FORM.f, ASK_FORM.t, 'Moved by hand'); R(); toast('Moved'); }
  if (a === 'stk-count') { const id = d.id || await stkPickProd(); if (!id) return; const p = crProd(id); const ok = await askBox('📝 Count — ' + p.name, `<div class="hint">Type how much is really there. The difference is written in the history as a stocktake.</div>${stkLocs().map((l) => `<div class="f"><label>${h(stkLocName(l))} (the app says ${stkFmt(p, stkQty(id, l))})</label>${stkInp('c_' + l, stkQty(id, l), 'number')}</div>`).join('')}`, 'Save the count'); if (!ok) return;
    stkLocs().forEach((l) => { const v = ASK_FORM['c_' + l]; if (v === '' || v == null) return; const diff = crR4(+v - stkQty(id, l)); if (!diff) return; if (diff > 0) stkAdd(id, diff, l, '', '', 'Stocktake'); else stkTake(id, -diff, l, 'Stocktake'); }); R(); toast('Counted'); }
  if (a === 'stk-vehadd' || a === 'stk-vehren') { const v = a === 'stk-vehren' ? stkVehicles().find((x) => x.id === d.id) : null; const ok = await askBox(v ? 'Vehicle' : '➕ Add a vehicle', `<div class="f"><label>Name (rego or what you call it)</label>${stkInp('n', v ? v.name : '')}</div>`, 'Save'); const n = (ASK_FORM.n || '').trim(); if (!ok || !n) return; stkCfgSave((c) => { c.vehicles = c.vehicles || []; if (v) c.vehicles.find((x) => x.id === v.id).name = n; else c.vehicles.push({ id: uid('veh'), name: n }); }); renderAll(); }
  if (a === 'stk-vehdel') { const v = stkVehicles().find((x) => x.id === d.id); if (!v) return; const left = stkL('stk').filter((x) => !x.gone && x.loc === v.id && x.qty > 0).length; if (!(await ask(`Remove ${v.name}?${left ? `\n\n${left} item${left === 1 ? ' is' : 's are'} still in it — move them back to the office first.` : ''}`, 'Yes — remove it', true))) return; stkCfgSave((c) => { c.vehicles.find((x) => x.id === v.id).gone = true; }); renderAll(); }
  if (a === 'stk-usualadd') { const id = await stkPickProd(); if (!id) return; const p = crProd(id); const ok = await askBox('Usual amount in ' + stkLocName(d.v), `<div class="f"><label>${h(p.name)}${stkUnit(p) ? ' (' + h(p.unit) + ')' : ''}</label>${stkInp('n', '', 'number')}</div>`, 'Save'); if (!ok || !(+ASK_FORM.n)) return; stkCfgSave((c) => { c.usual = c.usual || {}; c.usual[d.v] = { ...(c.usual[d.v] || {}), [id]: +ASK_FORM.n }; }); renderAll(); }
  if (a === 'stk-usualdel') { stkCfgSave((c) => { const u = { ...((c.usual || {})[d.v] || {}) }; delete u[d.id]; c.usual = { ...(c.usual || {}), [d.v]: u }; }); renderAll(); }
  if (a === 'stk-restock') { let n = 0; document.querySelectorAll('.stk-rs:checked').forEach((cb) => { const q = +((document.querySelector(`.stk-rq[data-id="${cb.dataset.id}"]`) || {}).value) || 0; if (q > 0) { stkMove(cb.dataset.id, q, 'office', d.v, 'Restocked ' + stkLocName(d.v)); n++; } });
    document.querySelectorAll('.stk-eqr:checked').forEach((cb) => { const e2 = stkL('stkeq').find((x) => x.id === cb.dataset.id); if (e2) { e2.loc = d.v; e2.state = 'ready'; touch(e2); n++; } }); R(); toast(n ? `✓ ${n} moved into ${stkLocName(d.v)}` : 'Nothing ticked'); }
  if (a === 'stk-eqadd' || a === 'stk-eqedit') { const e2 = a === 'stk-eqedit' ? stkL('stkeq').find((x) => x.id === d.id) : null; const ok = await askBox(e2 ? '🧰 ' + e2.name : '🧰 Add equipment', `<div class="f"><label>Name</label>${stkInp('n', e2 ? e2.name : '')}</div><div class="grid2"><div class="f"><label>Belongs in</label>${stkLocSel('home', e2 ? e2.home : (stkVehicles()[0] || {}).id || 'office')}</div><div class="f"><label>Where it is now</label>${stkLocSel('loc', e2 ? e2.loc : 'office')}</div></div>${e2 ? '<label class="bk-radio" style="display:flex"><input type="checkbox" data-askchk="del"> Delete it</label>' : ''}`, 'Save'); if (!ok) return;
    if (e2 && ASK_FORM.del) { e2.gone = true; touch(e2); R(); return; } const n = (ASK_FORM.n || '').trim(); if (!n) return; const r2 = e2 || { id: uid('eq'), state: 'ready' }; Object.assign(r2, { name: n, home: ASK_FORM.home, loc: ASK_FORM.loc }); touch(r2); if (!e2) stkL('stkeq').push(r2); R(); }
  if (a === 'stk-eqdirty' || a === 'stk-eqclean') { const e2 = stkL('stkeq').find((x) => x.id === d.id); if (!e2) return; if (a === 'stk-eqdirty') { e2.loc = 'office'; e2.state = 'dirty'; } else e2.state = 'ready'; touch(e2); R(); toast(a === 'stk-eqclean' ? `✓ Clean — it's on ${stkLocName(e2.home)}'s restock list` : 'Back at the office to clean'); }
  if (a === 'stk-poopen') { STK.po = d.id; renderAll(); } if (a === 'stk-poback') { STK.po = null; renderAll(); }
  const o = d.po && stkL('stkpo').find((x) => x.id === d.po); if (!o) return;
  if (a === 'stk-poadd') { const id = await stkPickProd(); if (!id) return; const p = crProd(id); o.lines.push({ prod: id, qty: p.reorder || 1, price: p.supPrice || p.cost || 0 }); if (!o.supName) { o.supName = stkSupName(p) === 'No supplier set' ? '' : stkSupName(p); o.sup = p.supplier || null; } touch(o); R(); }
  if (a === 'stk-podel') { o.lines.splice(+d.i, 1); touch(o); R(); }
  if (a === 'stk-podelpo') { if (!(await ask('Delete this order?', 'Yes — delete it', true))) return; o.gone = true; touch(o); STK.po = null; R(); }
  if (a === 'stk-poprint') { const w = window.open('', '_blank'); if (!w) { toast('Allow pop-ups to print'); return; } w.document.write(`<html><head><title>PO ${h(o.num)}</title><style>body{font-family:system-ui,sans-serif;padding:24px}th{text-align:left}</style></head><body>${stkPoBody(o)}</body></html>`); w.document.close(); setTimeout(() => w.print(), 300); }
  });
document.addEventListener('change', (e) => { const el = e.target; const a = el.dataset && el.dataset.act;
  if (a === 'stk-recveh') { const r = crGet('crrec', el.dataset.rec); if (!r) return; r.vehicle = el.value || null; touch(r); const sid = (r.staff || [])[0]; if (sid && el.value) stkCfgSave((c) => { c.day = { ...(c.day || {}), [sid + ':' + (r.date || bkToday())]: el.value }; }); stkSync(); }
  if (a === 'stk-bystaff') stkCfgSave((c) => { c.byStaff = { ...(c.byStaff || {}), [el.dataset.sid]: el.value || undefined }; });
  if (el.classList && el.classList.contains('stk-us')) stkCfgSave((c) => { c.usual = c.usual || {}; c.usual[el.dataset.v] = { ...(c.usual[el.dataset.v] || {}), [el.dataset.id]: +el.value || 0 }; });
  if (el.classList && el.classList.contains('stk-poq')) { const o = stkL('stkpo').find((x) => x.id === el.dataset.po); if (o) { o.lines[+el.dataset.i].qty = +el.value || 0; touch(o); stkSync(); } }
  if (el.classList && el.classList.contains('stk-ponote')) { const o = stkL('stkpo').find((x) => x.id === el.dataset.po); if (o) { o.note = el.value; touch(o); stkSync(); } }
  if (el.dataset && el.dataset.act === 'prep-veh') { const sid = el.dataset.sid, date = el.dataset.d; stkCfgSave((c) => { c.day = { ...(c.day || {}), [sid + ':' + date]: el.value || undefined }; }); renderAll(); } });
document.addEventListener('input', (e) => { if (e.target.id !== 'stk-q') return; STK.q = e.target.value; clearTimeout(STK._t); STK._t = setTimeout(() => { const pos = e.target.selectionStart; renderAll(); const n = document.getElementById('stk-q'); refocus(n, pos); }, 250); });
// today's vehicle, picked on Day prep
function stkPrepVeh(sid, date) { if (!stkVehicles().length) return ''; const v = stkDayVeh(sid, date); return `<div class="card"><label style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><b>🚗 Vehicle today</b><select data-act="prep-veh" data-sid="${sid}" data-d="${date}"><option value="">—</option>${stkVehicles().map((x) => `<option value="${x.id}" ${v === x.id ? 'selected' : ''}>${h(x.name)}</option>`).join('')}</select><span class="hint">records today take stock out of this one</span></label></div>`; }
window.stkHtml = stkHtml; window.stkRecBar = stkRecBar; window.stkPrepVeh = stkPrepVeh;

