// (used until the vehicles or supplier rules are first changed — then saved like everything else)
const stkSupRule = (name) => ((stkCfg().sup || {})[name]) || {};
const stkOnHand = (p) => stkQty(p.id);
function stkOrderQty(p) { const max = +p.max || (p.min ? +p.min + (+p.reorder || 0) : 0); let q = Math.max(0, crR4(max - stkOnHand(p) - stkOnOrder(p.id))); if (!q && p.min) q = +p.reorder || 1; if (p.moq && q < p.moq) q = +p.moq; if (p.supOuter > 1) q = Math.ceil(q / p.supOuter) * p.supOuter; return crR4(q); }
const stkOpenPo = (o) => !o.gone && ['draft', 'sent', 'part'].includes(o.status);
const stkLineLeft = (l) => (l.cancel ? 0 : Math.max(0, (+l.qty || 0) - (+l.got || 0)));
function stkOnOrder(pid) { return stkL('stkpo').filter((o) => stkOpenPo(o) && o.status !== 'draft').reduce((s, o) => s + (o.lines || []).filter((l) => l.prod === pid).reduce((a, l) => a + stkLineLeft(l), 0), 0); }
function stkReorder() { return crList('crprod').filter((p) => !p.gone && stkTracked(p) && p.min && stkOnHand(p) + stkOnOrder(p.id) <= p.min && !stkL('stkpo').some((o) => stkOpenPo(o) && o.status === 'draft' && (o.lines || []).some((l) => l.prod === p.id))); }
const stkPoTotal = (o) => crR2((o.lines || []).filter((l) => !l.cancel).reduce((s, l) => s + (+l.qty || 0) * (+l.price || 0), 0));
function stkNextPo(supName, sup, urgent) { let o = stkL('stkpo').find((x) => !x.gone && x.status === 'draft' && !x.urgent === !urgent && (x.supName || '') === (supName || '')); if (o) return o;
  let num = ''; stkCfgSave((c) => { num = 'PO' + String(c.poNext || 1).padStart(4, '0'); c.poNext = (c.poNext || 1) + 1; });
  o = { id: uid('po'), num, at: Date.now(), by: SBAuth.staff && SBAuth.staff.id, status: 'draft', urgent: !!urgent, sup: sup || (supName && (D.businesses.find((b) => !b.gone && b.name === supName) || {}).id) || null, supName: supName && supName !== 'No supplier set' ? supName : '', note: '', lines: [] }; touch(o); stkL('stkpo').push(o); return o; }
function stkPoAddProd(o, p, q) { const l = o.lines.find((x) => x.prod === p.id && !x.cancel); if (l) l.qty = crR4((+l.qty || 0) + (q || stkOrderQty(p))); else o.lines.push({ prod: p.id, qty: q || stkOrderQty(p) || 1, price: p.supPrice || p.cost || 0 }); touch(o); }
function stkNewPo(supName) { const R = supName ? stkReorder().filter((p) => stkSupName(p) === supName) : []; const o = stkNextPo(supName, R[0] && R[0].supplier, false); R.forEach((p) => stkPoAddProd(o, p)); stkSync(); STK.po = o.id; STK.tab = 'orders'; renderAll(); }
function stkPoChecks(o) { const rule = stkSupRule(o.supName); const tot = stkPoTotal(o); const out = [];
  if (rule.minTotal && tot < rule.minTotal) out.push({ k: 'min', t: `Below ${o.supName}'s minimum order of ${crMoney(rule.minTotal)} ex GST${rule.note ? ' (' + rule.note + ')' : ''} — ${crMoney(rule.minTotal - tot)} short.` });
  if (rule.minLines && (o.lines || []).filter((l) => !l.cancel).length < rule.minLines) out.push({ k: 'lines', t: `${o.supName} needs at least ${rule.minLines} items on an order.` });
  (o.lines || []).forEach((l) => { const p = crProd(l.prod); if (!p || l.cancel) return; if (p.moq && +l.qty < p.moq) out.push({ k: 'moq', t: `${p.name}: ${o.supName || 'the supplier'} sells at least ${stkFmt(p, p.moq)}.` }); if (p.supOuter > 1 && +l.qty % p.supOuter) out.push({ k: 'outer', t: `${p.name}: comes in packs of ${p.supOuter}.` }); });
  return out; }
function stkPoSuggest(o) { const have = new Set((o.lines || []).map((l) => l.prod)); return crList('crprod').filter((p) => !p.gone && stkTracked(p) && !have.has(p.id) && stkSupName(p) === (o.supName || '-')).map((p) => { const max = +p.max || (p.min ? +p.min + (+p.reorder || 0) : 0); const room = Math.max(0, max - stkOnHand(p) - stkOnOrder(p.id)); return { p, room, near: p.min ? (stkOnHand(p) - p.min) / Math.max(1, p.min) : 9 }; }).filter((x) => x.room > 0 || !x.p.max).sort((a, b) => a.near - b.near).slice(0, 12); }
function stkOrdersHtml() { const R = stkReorder(); const g = {}; R.forEach((p) => (g[stkSupName(p)] = g[stkSupName(p)] || []).push(p)); const POs = stkL('stkpo').filter((o) => !o.gone).sort((a, b) => b.at - a.at); const sn = { draft: 'Draft', sent: 'Sent', part: 'Part received', done: 'Received' };
  const next = POs.filter((o) => o.status === 'draft'); const bo = POs.filter((o) => o.status === 'part' || o.status === 'sent').flatMap((o) => (o.lines || []).filter((l) => l.bo && stkLineLeft(l) > 0).map((l) => ({ o, l })));
  const row = (o) => { const rule = stkSupRule(o.supName); const tot = stkPoTotal(o); return `<div class="kv bk-tap" data-act="stk-poopen" data-id="${o.id}"><div class="k">${bkDate(new Date(o.at).toISOString().slice(0, 10), { day: 'numeric', month: 'short' })}</div><div class="v"><b>${o.urgent ? '⚡ ' : ''}PO ${h(o.num)}</b> — ${h(o.supName || '')} <span class="pill" style="font-size:11px">${o.status === 'draft' ? (o.urgent ? 'Urgent — to send now' : 'Next order (building up)') : sn[o.status] || o.status}</span><br><span class="hint">${(o.lines || []).length} item${(o.lines || []).length === 1 ? '' : 's'} · ${crMoney(tot)} ex GST${rule.minTotal && o.status === 'draft' ? ` of ${crMoney(rule.minTotal)} minimum` : ''}</span></div></div>`; };
  return `<div class="card"><h3>To order — at or below their minimum</h3><div class="hint">Each item is ordered up to its maximum (maximum less what's on hand and already on order).</div>${Object.keys(g).length ? Object.entries(g).map(([s2, L]) => `<div class="kv" style="align-items:flex-start;flex-wrap:wrap"><div class="v" style="flex:1"><b>${h(s2)}</b><div class="hint">${L.map((p) => `${h(p.name)}: ${stkFmt(p, stkOnHand(p))} on hand, order ${stkFmt(p, stkOrderQty(p))}`).join('<br>')}</div></div><button class="btn small" data-act="stk-ponew" data-sup="${h(s2)}">🧾 Add to the next order</button><button class="btn small" data-act="stk-urgentnew" data-sup="${h(s2)}">⚡ Urgent — order now</button></div>`).join('') : '<div class="hint">Nothing at or below its minimum. (Set minimum and maximum on each item in Stock.)</div>'}
    <div class="actions"><button class="btn small" data-act="stk-ponew">➕ New order</button></div></div>
    ${bo.length ? `<div class="card"><h3>⏳ On backorder</h3>${bo.map(({ o, l }) => { const p = crProd(l.prod); const late = l.bo.exp && l.bo.exp < bkToday(); return `<div class="kv" style="align-items:center;flex-wrap:wrap"><div class="v" style="flex:1"><b>${h(p ? p.name : '?')}</b> × ${stkLineLeft(l)} — ${h(o.supName || '')} (PO ${h(o.num)})<br><span class="hint" ${late ? 'style="color:var(--red)"' : ''}>${l.bo.exp ? (late ? 'was expected ' : 'expected ') + bkDate(l.bo.exp, { day: 'numeric', month: 'short' }) : 'no date given'}${l.bo.note ? ' · ' + h(l.bo.note) : ''}</span></div><button class="btn small primary" data-act="stk-porecv" data-po="${o.id}">📥 Arrived</button><button class="btn small" data-act="stk-boelse" data-po="${o.id}" data-p="${l.prod}">↪ Order elsewhere</button><button class="btn small" data-act="stk-bocancel" data-po="${o.id}" data-p="${l.prod}">✕ Not coming</button></div>`; }).join('')}</div>` : ''}
    ${next.length ? `<div class="card"><h3>Draft orders</h3>${next.map(row).join('')}</div>` : ''}
    <div class="card"><h3>Sent and received</h3>${POs.filter((o) => o.status !== 'draft').map(row).join('') || '<div class="hint">None yet.</div>'}</div>`; }
const stkBoCount = () => stkL('stkpo').filter((o) => !o.gone && (o.status === 'part' || o.status === 'sent')).reduce((s, o) => s + (o.lines || []).filter((l) => l.bo && stkLineLeft(l) > 0 && l.bo.exp && l.bo.exp < bkToday()).length, 0);
function stkPoHtml(id) { const o = stkL('stkpo').find((x) => x.id === id && !x.gone); if (!o) { STK.po = null; return stkOrdersHtml(); } const ed = o.status === 'draft'; const sup = o.sup && IDX.biz.get(o.sup); const em = sup ? (sup.emails || []).map((e) => e.value).filter(Boolean) : []; const chk = ed ? stkPoChecks(o) : []; const sug = ed && chk.some((c) => c.k === 'min') ? stkPoSuggest(o) : [];
  return `<div class="actions"><button class="btn small" data-act="stk-poback">‹ Orders</button></div><h3>${o.urgent ? '⚡ Urgent ' : ''}Purchase order ${h(o.num)} — ${h(o.supName || 'supplier')}</h3><div class="hint">${o.status === 'draft' ? (o.urgent ? 'Urgent — to send now' : 'Next order — add to it until you send it') : o.status === 'sent' ? 'Sent ' + (o.sentAt ? new Date(o.sentAt).toLocaleDateString('en-AU') : '') + (o.sentTo ? ' to ' + h(o.sentTo) : '') : o.status === 'part' ? 'Part received' : 'Received'}${o.freight ? ` · urgent freight ${crMoney(o.freight.amt)} charged to ${h((IDX.biz.get(o.freight.bid) || {}).name || '')}` : ''}</div>
    ${chk.length ? `<div class="bk-warnbox">${chk.map((c) => '⚠ ' + h(c.t)).join('<br>')}</div>` : ''}
    <div class="card"><table class="ezy-t"><tr><th>Item</th><th>Their code</th><th>Qty</th><th>Price ex GST</th>${o.status !== 'draft' ? '<th>Received</th>' : ''}<th></th></tr>${(o.lines || []).map((l, i) => { const p = crProd(l.prod); return `<tr ${l.cancel ? 'style="opacity:.5;text-decoration:line-through"' : ''}><td>${h(p ? p.name : l.name || '?')}${l.bo && stkLineLeft(l) ? ' <span class="pill" style="font-size:11px">⏳ backorder</span>' : ''}</td><td>${h((p && p.supCode) || '')}</td><td>${ed ? `<input type="number" class="stk-poq" data-po="${o.id}" data-i="${i}" value="${l.qty}" min="0" step="any" style="width:70px">` : l.qty}</td><td>${crMoney(l.price || 0)}</td>${o.status !== 'draft' ? `<td>${+l.got || 0}</td>` : ''}<td>${ed ? `<button class="btn small" data-act="stk-podel" data-po="${o.id}" data-i="${i}">✕</button>` : ''}</td></tr>`; }).join('')}
      <tr><td colspan="3"><b>Total ex GST</b></td><td><b>${crMoney(stkPoTotal(o))}</b></td></tr></table>
      ${ed ? `<div class="actions"><button class="btn small" data-act="stk-poadd" data-po="${o.id}">➕ Add an item</button></div>` : ''}
      ${sug.length ? `<div class="lbl" style="margin-top:8px">Other ${h(o.supName)} items you could add to make up the minimum</div>${sug.map((x) => `<div class="kv" style="align-items:center"><div class="v">${h(x.p.name)} <span class="hint">${stkFmt(x.p, stkOnHand(x.p))} on hand${x.p.max ? ', room for ' + stkFmt(x.p, x.room) : ''} · ${crMoney(x.p.supPrice || x.p.cost || 0)} each</span></div><button class="btn small" data-act="stk-posug" data-po="${o.id}" data-p="${x.p.id}" data-q="${x.room || x.p.moq || 1}">➕ ${x.room || x.p.moq || 1}</button></div>`).join('')}` : ''}
      <div class="f"><label>Note to the supplier</label><textarea class="stk-ponote" data-po="${o.id}" rows="2" ${ed ? '' : 'disabled'}>${h(o.note || '')}</textarea></div></div>
    <div class="actions">${ed ? `<button class="btn primary" data-act="stk-posend" data-po="${o.id}">📧 Send to ${h(em[0] || 'the supplier')}</button>${o.urgent ? '' : `<button class="btn" data-act="stk-mkurgent" data-po="${o.id}">⚡ It's urgent — send now</button>`}` : ''}${o.status === 'sent' || o.status === 'part' ? `<button class="btn primary" data-act="stk-porecv" data-po="${o.id}">📥 It's arrived — receive it</button>` : ''}<button class="btn" data-act="stk-poprint" data-po="${o.id}">🖨 Print / PDF</button>${ed ? `<button class="btn" data-act="stk-podelpo" data-po="${o.id}" style="color:var(--red)">Delete</button>` : ''}</div>
    ${!em.length && ed ? `<div class="hint">${h(o.supName || 'This supplier')} has no email in the app yet — add one on their business, or it opens your email to type it.</div>` : ''}`; }
function stkSupHtml() { const names = [...new Set([...crList('crprod').filter((p) => !p.gone && stkTracked(p)).map(stkSupName), ...Object.keys(stkCfg().sup || {})])].filter((n) => n && n !== 'No supplier set').sort();
  return `<div class="card"><h3>Suppliers' ordering rules</h3><div class="hint">An order that doesn't meet these gets a warning (and suggestions of what else to add) before it's sent.</div>${names.map((n) => { const r = stkSupRule(n); return `<div class="kv" style="align-items:center"><div class="v"><b>${h(n)}</b><br><span class="hint">${[r.minTotal ? 'minimum order ' + crMoney(r.minTotal) + ' ex GST' : '', r.freight ? 'freight ' + crMoney(r.freight) + ' if under' : '', r.minLines ? 'at least ' + r.minLines + ' items' : '', r.note].filter(Boolean).map(h).join(' · ') || 'no rules'}</span></div><button class="btn small" data-act="stk-supedit" data-n="${h(n)}">✏️</button></div>`; }).join('') || '<div class="hint">No suppliers yet — they come from the price list (each item\'s supplier).</div>'}
    <div class="hint" style="margin-top:6px">Each item's own minimum order amount (and pack size) is on the item in Stock → ✏️ next to its minimum.</div></div>`; }
async function stkChargeFreight(o, amt) { const ok = await askBox('⚡ Urgent freight — who pays?', `<div class="f"><label>Charge the urgent freight to (the client it's for)</label><input data-ask="b" list="stk-cl" style="width:100%;padding:9px;font-size:16px"><datalist id="stk-cl">${D.businesses.filter((b) => !b.gone && isClientBiz(b) && !INACT.includes(bizCat(b))).map((b) => `<option value="${h(b.name)}">`).join('')}</datalist></div><div class="f"><label>Freight (ex GST, $)</label><input data-ask="f" type="number" min="0" step="0.01" value="${amt || ''}" style="width:140px;padding:9px;font-size:16px"></div><div class="hint">It's added to that client's invoice as "Urgent freight" (a new invoice if they don't have one open).</div>`, 'Charge it', false, 'Skip — we pay');
  if (!ok) return; const b = D.businesses.find((x) => !x.gone && x.name.toLowerCase() === (ASK_FORM.b || '').trim().toLowerCase()); const f = +ASK_FORM.f || 0; if (!b || !f) { toast(b ? 'Type the freight amount' : 'Choose the client from the list'); return; }
  let pr = crList('crprod').find((p) => p.id === 'p-urgent-freight'); if (!pr) { pr = { id: 'p-urgent-freight', cat: 'service', name: 'Urgent freight', unit: 'each', price: 0, gst: true, active: true }; touch(pr); D.crprod.push(pr); }
  let inv = crList('crinv').filter((x) => !x.gone && x.bid === b.id && ['notready', 'pending'].includes(x.status)).sort((a, c) => (c.date || '').localeCompare(a.date || ''))[0];
  if (!inv) { inv = { id: uid('inv'), rec: null, bid: b.id, date: bkToday(), status: 'pending', lines: [], log: [], at: Date.now() }; crList('crinv').push(inv); }
  inv.lines.push({ id: uid('il'), prod: pr.id, gst: true, desc: `Urgent freight — ${o.supName || 'supplier'} order ${o.num}`, qty: 1, price: f, auto: false }); if (typeof crInvLog === 'function') crInvLog(inv, `Added urgent freight ${crMoney(f)} (PO ${o.num})`); touch(inv); o.freight = { bid: b.id, amt: f, inv: inv.id }; touch(o); toast(`Urgent freight ${crMoney(f)} added to ${b.name}'s invoice`); }
async function stkSend(o) { if (!o.lines.filter((l) => !l.cancel).length) { toast('Add the items first'); return; } const chk = stkPoChecks(o); const rule = stkSupRule(o.supName);
  if (chk.length) { const r2 = await askBox(o.urgent ? '⚡ Send it anyway?' : 'This order doesn\'t meet the rules', `<div class="bk-warnbox">${chk.map((c) => '⚠ ' + h(c.t)).join('<br>')}</div><p>${o.urgent ? 'It\'s urgent, so you can send it now and pay the freight.' : 'Add more (see the suggestions), keep it as the next order, or mark it urgent and send it now.'}</p>`, o.urgent ? 'Send it now' : '⚡ Urgent — send it now', false, 'Go back'); if (!r2) return; if (!o.urgent) { o.urgent = true; touch(o); } }
  const sup = o.sup && IDX.biz.get(o.sup);
  if (typeof emlCompose === 'function') { const L = (o.lines || []).filter((l) => !l.cancel); const nm = (l) => { const p = crProd(l.prod); return p ? p.name : l.name || ''; }; const cd = (l) => { const p = crProd(l.prod); return (p && p.supCode) || ''; };
    const tbl = { text: L.map((l) => `${l.qty} × ${nm(l)}${cd(l) ? ' (your code ' + cd(l) + ')' : ''}`).join('\n'), html: `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse"><tr><th>Your code</th><th>Item</th><th>Qty</th><th>Price ex GST</th></tr>${L.map((l) => `<tr><td>${h(cd(l))}</td><td>${h(nm(l))}</td><td style="text-align:right">${l.qty}</td><td style="text-align:right">${crMoney(l.price || 0)}</td></tr>`).join('')}</table>` };
    const V = { 'supplier name': o.supName || (sup && sup.name) || '', 'PO number': o.num, 'order table': tbl, 'order total': crMoney(stkPoTotal(o)) + ' ex GST', 'supplier wording': (sup && sup.poText) || '', note: o.note || '' };
    const em = sup ? (sup.emails || []).map((x) => x.value).filter(Boolean) : [];
    await emlCompose({ use: 'po', bid: sup ? sup.id : null, V, to: em.slice(0, 1), title: '📧 Send purchase order ' + o.num, onSent: async (inf) => { o.status = 'sent'; o.sentAt = Date.now(); o.sentTo = inf.to.join(', '); touch(o); if (o.urgent && rule.minTotal && stkPoTotal(o) < rule.minTotal) await stkChargeFreight(o, rule.freight); stkSync(); renderAll(); } });
    if (o.urgent) { const sb = document.getElementById('em-sub'); if (sb && !/^URGENT/.test(sb.value)) sb.value = 'URGENT — ' + sb.value; }
    return; }
  const em = sup ? (sup.emails || []).map((x) => x.value).filter(Boolean) : [];
  const ok = await askBox('📧 Send purchase order ' + o.num, `<div class="f"><label>To</label>${stkInp('to', em[0] || '')}</div><div class="hint">Sent from the practice email with the order in the email${o.note ? ' and your note' : ''}. A copy goes to the office.</div>`, 'Send'); if (!ok) return; const to = (ASK_FORM.to || '').trim(); if (!/@/.test(to)) { toast('Type the supplier\'s email address'); return; }
  let sent = false; try { const r = await sbFetch('/functions/v1/mail', { method: 'POST', body: JSON.stringify({ k: Dev.k(), to: [to], cc: ['office@bovitech.com.au'], subject: `${o.urgent ? 'URGENT — ' : ''}Purchase order ${o.num} — Bovitech Veterinary Services`, html: stkPoBody(o), text: stkPoText(o) }) }); sent = r.ok; } catch (x) { console.warn(x); }
  if (!sent) { location.href = `mailto:${encodeURIComponent(to)}?cc=office@bovitech.com.au&subject=${encodeURIComponent((o.urgent ? 'URGENT — ' : '') + 'Purchase order ' + o.num + ' — Bovitech Veterinary Services')}&body=${encodeURIComponent(stkPoText(o))}`; toast("The app can't send email yet (Admin jobs → Email from the app) — it's opened in your email instead"); }
  o.status = 'sent'; o.sentAt = Date.now(); o.sentTo = to; touch(o); if (o.urgent && rule.minTotal && stkPoTotal(o) < rule.minTotal) await stkChargeFreight(o, rule.freight); stkSync(); renderAll(); if (sent) toast('📧 Sent to ' + to); }
async function stkReceive(o) { const open = o.lines.map((l, i) => ({ l, i })).filter((x) => stkLineLeft(x.l) > 0);
  const ok = await askBox('📥 Receive ' + o.num, `<div class="hint">How much came, its batch and expiry (it goes into the office). If some didn't come, say what's happening with the rest.</div>${open.map(({ l, i }) => { const p = crProd(l.prod); const left = stkLineLeft(l); return `<div class="card" style="padding:8px;margin:6px 0"><b>${h(p ? p.name : '?')}</b> <span class="hint">ordered ${l.qty}${l.got ? ', ' + l.got + ' already in' : ''}</span><div class="grid2"><div class="f"><label>Received${p && stkUnit(p) ? ' (' + h(p.unit) + ')' : ''}</label>${stkInp('q' + i, left, 'number')}</div><div class="f"><label>Batch</label>${stkInp('b' + i, '')}</div><div class="f"><label>Expiry</label>${stkInp('x' + i, '', 'date')}</div>
      <div class="f"><label>If not all of it came, the rest is…</label><select data-ask="r${i}" style="width:100%;padding:9px;font-size:16px"><option value="bo">On backorder</option><option value="cancel">Not coming — cancelled</option></select></div><div class="f"><label>Backorder expected</label>${stkInp('e' + i, '', 'date')}</div></div></div>`; }).join('')}`, 'Put it in stock'); if (!ok) return;
  open.forEach(({ l, i }) => { const q = +ASK_FORM['q' + i] || 0; if (q) { stkAdd(l.prod, q * (l.per || 1), 'office', ASK_FORM['b' + i], ASK_FORM['x' + i], 'Received — ' + o.num, o.id); l.got = crR4((+l.got || 0) + q); } if (stkLineLeft(l) > 0) { if (ASK_FORM['r' + i] === 'cancel') l.cancel = true; else l.bo = { exp: ASK_FORM['e' + i] || (l.bo && l.bo.exp) || '', at: Date.now() }; } else delete l.bo; });
  o.status = o.lines.every((l) => stkLineLeft(l) <= 0) ? 'done' : 'part'; o.recvAt = Date.now(); touch(o); stkSync(); renderAll(); toast(o.status === 'done' ? '✓ All received' : '⏳ Part received — the rest is on backorder'); }

/* ---------- 📸 product photos: a picture library the app matches against when there's no barcode ---------- */
const STK_FW = 16; // features: a small colour picture (16×16) and a colour histogram — simple, works offline, gets better with more photos
async function stkImg(file) { const url = URL.createObjectURL(file); const img = await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = url; }); URL.revokeObjectURL(url); return img; }
function stkThumb(src, w) { const c = document.createElement('canvas'); const s = Math.min(src.videoWidth || src.width, src.videoHeight || src.height); const sx = ((src.videoWidth || src.width) - s) / 2, sy = ((src.videoHeight || src.height) - s) / 2; c.width = c.height = w; const x = c.getContext('2d'); x.drawImage(src, sx, sy, s, s, 0, 0, w, w); return c; }
function stkFeat(src) { const c = stkThumb(src, STK_FW); const d = c.getContext('2d').getImageData(0, 0, STK_FW, STK_FW).data; const f = []; const hist = new Array(64).fill(0); let m = 0;
  for (let i = 0; i < d.length; i += 4) { const r = d[i], g = d[i + 1], b = d[i + 2]; f.push(r / 255, g / 255, b / 255); hist[((r >> 6) << 4) | ((g >> 6) << 2) | (b >> 6)]++; }
  const mean = f.reduce((a, b) => a + b, 0) / f.length; const v = f.map((x) => x - mean); hist.forEach((x) => v.push((x / (STK_FW * STK_FW)) * 6)); v.forEach((x) => (m += x * x)); m = Math.sqrt(m) || 1; return v.map((x) => Math.round((x / m) * 1000) / 1000); }
const stkCos = (a, b) => { let s = 0; const n = Math.min(a.length, b.length); for (let i = 0; i < n; i++) s += a[i] * b[i]; return s; };
function stkMatch(feat) { const best = {}; stkL('stkphoto').filter((x) => !x.gone && x.f).forEach((x) => { const s = stkCos(feat, x.f); if (!best[x.prod] || s > best[x.prod]) best[x.prod] = s; }); return Object.entries(best).map(([prod, s]) => ({ p: crProd(prod), s })).filter((x) => x.p).sort((a, b) => b.s - a.s).slice(0, 4); }
function stkSavePhoto(prod, src) { const r = { id: uid('ph'), prod, img: stkThumb(src, 160).toDataURL('image/jpeg', 0.7), f: stkFeat(src), at: Date.now(), by: SBAuth.staff && SBAuth.staff.id }; touch(r); stkL('stkphoto').push(r); stkSync(); return r; }
async function stkPhotoPick(capture) { return new Promise((res) => { const i = document.createElement('input'); i.type = 'file'; i.accept = 'image/*'; if (capture) i.capture = 'environment'; i.onchange = async () => { const f = i.files && i.files[0]; res(f ? await stkImg(f) : null); }; i.click(); }); }
async function stkRecognise(src) { // → product, or null — learns from every confirmed match
  const feat = stkFeat(src); const M = stkMatch(feat); const prev = stkThumb(src, 120).toDataURL('image/jpeg', 0.7);
  const ok = await askBox('📸 Which product is it?', `<div style="display:flex;gap:10px;align-items:center"><img src="${prev}" alt="" style="width:90px;height:90px;border-radius:8px;object-fit:cover"><div class="hint">${M.length ? 'Best matches from the photo library — tap the right one.' : 'No photos in the library yet — choose the product and this photo is saved for next time.'}</div></div>
    ${M.map((x, i) => { const ph = stkL('stkphoto').find((y) => !y.gone && y.prod === x.p.id); return `<label class="bk-radio" style="display:flex;align-items:center;gap:8px;margin:6px 0"><input type="radio" name="sm" data-ask="m" value="${i}" ${i ? '' : 'checked'}>${ph ? `<img src="${ph.img}" alt="" style="width:44px;height:44px;border-radius:6px;object-fit:cover">` : ''} ${h(x.p.name)} <span class="hint">${Math.round(Math.max(0, x.s) * 100)}%</span></label>`; }).join('')}
    <label class="bk-radio" style="display:flex;margin:6px 0"><input type="radio" name="sm" data-ask="m" value="pick" ${M.length ? '' : 'checked'}> Not these — choose the product…</label>`, 'Next'); if (!ok) return null;
  let p = ASK_FORM.m === 'pick' || !M.length ? null : M[+ASK_FORM.m || 0].p; if (!p) { const id = await crPickProd(['med', 'consumable', 'merch']); p = id && crProd(id); } if (!p) return null; stkSavePhoto(p.id, src); return p; }
function stkPhotosHtml() { const P = stkL('stkphoto').filter((x) => !x.gone); const by = {}; P.forEach((x) => (by[x.prod] = by[x.prod] || []).push(x));
  return `<div class="card"><h3><span class="sp">📸 Product photos</span><button class="btn small" data-act="stk-photo">➕ Add a photo</button></h3><div class="hint">When something has no barcode, take a photo of it while scanning and the app picks the closest matches from these. Each time you confirm a match the photo is added, so it gets better. Several brands of the same thing can share a product, and one product can have lots of photos.</div>
    ${Object.entries(by).map(([pid, L]) => { const p = crProd(pid); return p ? `<div class="kv" style="align-items:center;flex-wrap:wrap"><div class="v" style="flex:1"><b>${h(p.name)}</b> <span class="hint">${L.length} photo${L.length === 1 ? '' : 's'}</span><div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:4px">${L.slice(0, 8).map((x) => `<img src="${x.img}" alt="" style="width:48px;height:48px;border-radius:6px;object-fit:cover" data-act="stk-phdel" data-id="${x.id}" title="Tap to remove">`).join('')}</div></div><button class="btn small" data-act="stk-photo" data-id="${pid}">➕</button></div>` : ''; }).join('') || '<div class="hint">None yet.</div>'}</div>`; }
// the Stock page and the record bar, with the new tabs and the barcode icon
const stkHtml0 = stkHtml; stkHtml = function () { if (STK.tab === 'suppliers') return `<div class="d-wrap"><h2 class="sec-h" style="font-size:26px">📦 Stock and ordering</h2>${stkTabsHtml()}${stkSupHtml()}</div>`; if (STK.tab === 'photos') return `<div class="d-wrap"><h2 class="sec-h" style="font-size:26px">📦 Stock and ordering</h2>${stkTabsHtml()}${stkPhotosHtml()}</div>`; return stkHtml0().replace(/📷 /g, ''); };
function stkTabsHtml() { return `<div class="chips" style="margin-bottom:8px">${STK_TABS.map(([k, l]) => `<button class="chip ${STK.tab === k ? 'on' : ''}" data-act="stk-tab" data-v="${k}">${l}</button>`).join('')}</div>`; }
const stkRecBar0 = stkRecBar; stkRecBar = function (r) { return stkRecBar0(r).replace('📷 Scan what you used', STK_BC + ' Scan what you used').replace('>📷 Scan<', '>' + STK_BC + ' Scan<'); };
window.stkHtml = stkHtml; window.stkRecBar = stkRecBar;
// photos inside the scanner
document.addEventListener('click', async (e) => { const el = e.target.closest && e.target.closest('[data-act]'); if (!el) return; const a = el.dataset.act; if (!/^stk-/.test(a)) return; const d = el.dataset; const R = () => { stkSync(); renderAll(); };
  if (a === 'stk-ponew') stkNewPo(d.sup || '');
  if (a === 'stk-urgentnew') { const L = stkReorder().filter((p) => stkSupName(p) === d.sup); const o = stkNextPo(d.sup, L[0] && L[0].supplier, true); L.forEach((p) => stkPoAddProd(o, p)); R(); STK.po = o.id; STK.tab = 'orders'; renderAll(); }
  if (a === 'stk-next') { const p = crProd(d.id); if (!p) return; const o = stkNextPo(stkSupName(p), p.supplier, false); stkPoAddProd(o, p); R(); toast(`Added to the next ${o.supName || ''} order (${o.num}) — ${crMoney(stkPoTotal(o))} so far`); }
  if (a === 'stk-mkurgent') { const o = stkL('stkpo').find((x) => x.id === d.po); if (!o) return; o.urgent = true; touch(o); await stkSend(o); }
  if (a === 'stk-posend') { const o = stkL('stkpo').find((x) => x.id === d.po); if (o) await stkSend(o); }
  if (a === 'stk-porecv') { const o = stkL('stkpo').find((x) => x.id === d.po); if (o) await stkReceive(o); }
  if (a === 'stk-posug') { const o = stkL('stkpo').find((x) => x.id === d.po); const p = crProd(d.p); if (o && p) { stkPoAddProd(o, p, +d.q || 1); R(); } }
  if (a === 'stk-bocancel' || a === 'stk-boelse') { const o = stkL('stkpo').find((x) => x.id === d.po); const l = o && o.lines.find((x) => x.prod === d.p && stkLineLeft(x) > 0); if (!l) return; const p = crProd(d.p); const left = stkLineLeft(l);
    if (a === 'stk-boelse') { const ok = await askBox('↪ Order it from another supplier', `<div class="f"><label>Supplier</label><input data-ask="s" list="stk-sl2" style="width:100%;padding:9px;font-size:16px"><datalist id="stk-sl2">${D.businesses.filter((b) => !b.gone && !isClientBiz(b)).map((b) => `<option value="${h(b.name)}">`).join('')}</datalist></div><label class="bk-radio" style="display:flex"><input type="checkbox" data-askchk="u"> ⚡ Urgent — send it now</label>`, 'Add to their order'); if (!ok || !(ASK_FORM.s || '').trim()) return;
      const sb = D.businesses.find((b) => !b.gone && b.name.toLowerCase() === ASK_FORM.s.trim().toLowerCase()); const n = stkNextPo(sb ? sb.name : ASK_FORM.s.trim(), sb && sb.id, !!ASK_FORM.u); stkPoAddProd(n, p, left); l.cancel = true; delete l.bo; touch(o); STK.po = n.id; }
    else { if (!(await ask(`Cancel the ${left} ${p ? p.name : ''} still to come on ${o.num}?`, 'Yes — not coming'))) return; l.cancel = true; delete l.bo; }
    if (o.lines.every((x) => stkLineLeft(x) <= 0)) o.status = 'done'; touch(o); R(); }
  if (a === 'stk-supedit') { const n = d.n; const r = stkSupRule(n); const ok = await askBox('Ordering rules — ' + n, `<div class="grid2"><div class="f"><label>Minimum order (ex GST, $)</label>${stkInp('t', r.minTotal || '', 'number')}</div><div class="f"><label>Freight if under it (ex GST, $)</label>${stkInp('f', r.freight || '', 'number')}</div><div class="f"><label>At least this many items</label>${stkInp('l', r.minLines || '', 'number')}</div></div><div class="f"><label>Note</label>${stkInp('n', r.note || '')}</div>`, 'Save'); if (!ok) return;
    stkCfgSave((c) => { c.sup = { ...(c.sup || {}), [n]: { minTotal: +ASK_FORM.t || null, freight: +ASK_FORM.f || null, minLines: +ASK_FORM.l || null, note: (ASK_FORM.n || '').trim() } }; }); renderAll(); }
  if (a === 'stk-min') { const p = crProd(d.id); const ok = await askBox('Stock levels — ' + p.name, `<div class="grid2"><div class="f"><label>Minimum (order when it gets to this)</label>${stkInp('m', p.min || '', 'number')}</div><div class="f"><label>Maximum (order up to this)</label>${stkInp('x', p.max || '', 'number')}</div><div class="f"><label>Supplier's minimum order</label>${stkInp('q', p.moq || '', 'number')}</div><div class="f"><label>Comes in packs of</label>${stkInp('o', p.supOuter || '', 'number')}</div></div><div class="f"><label>Supplier</label><input data-ask="s" list="stk-sl" value="${h(stkSupName(p) === 'No supplier set' ? '' : stkSupName(p))}" style="width:100%;padding:9px;font-size:16px"><datalist id="stk-sl">${D.businesses.filter((b) => !b.gone && !isClientBiz(b)).map((b) => `<option value="${h(b.name)}">`).join('')}</datalist></div><div class="grid2"><div class="f"><label>Their code</label>${stkInp('c', p.supCode || '')}</div><div class="f"><label>Their price ex GST</label>${stkInp('pp', p.supPrice || '', 'number')}</div></div>`, 'Save'); if (!ok) return;
    p.min = +ASK_FORM.m || null; p.max = +ASK_FORM.x || null; p.moq = +ASK_FORM.q || null; p.supOuter = +ASK_FORM.o || null; const sb = D.businesses.find((b) => !b.gone && b.name.toLowerCase() === (ASK_FORM.s || '').trim().toLowerCase()); p.supplier = sb ? sb.id : null; p.supName = (ASK_FORM.s || '').trim() || null; p.supCode = ASK_FORM.c || null; p.supPrice = +ASK_FORM.pp || null; touch(p); R(); }
  if (a === 'stk-photo') { const id = d.id || await crPickProd(['med', 'consumable', 'merch']); if (!id) return; const img = await stkPhotoPick(true); if (!img) return; stkSavePhoto(id, img); renderAll(); toast('📸 Photo added'); }
  if (a === 'stk-phdel') { const x = stkL('stkphoto').find((y) => y.id === d.id); if (!x || !(await ask('Remove this photo?', 'Yes — remove it', true))) return; x.gone = true; touch(x); R(); } });
